// Query execution function compatible with existing runQuery interface
export async function runPostgresQuery(sql: string, params: any[] = [], type: 'run' | 'all' = 'run'): Promise<any> {
  const client = await pool.connect();
  try {
    if (type === 'all') {
      const result = await client.query(sql, params);
      return result.rows;
    } else {
      const result = await client.query(sql, params);
      return {
        changes: result.rowCount || 0,
        lastInsertRowid: result.rows?.[0]?.id || undefined
      };
    }
  } finally {
    client.release();
  }
}

// Migration function to copy data from SQLite to PostgreSQL
export async function migrateFromSQLite(sqliteDbPath: string) {
  const Database = (await import('better-sqlite3')).default;
  const sqliteDb = Database(sqliteDbPath);

  console.log('Starting migration from SQLite to PostgreSQL...');

  const tables = ['candles', 'trades', 'shadow_trades', 'daily_performance', 'regime_history', 'settings', 'balances', 'market_data', 'market_news'];

  for (const table of tables) {
    console.log(`Migrating table: ${table}`);

    const rows = sqliteDb.prepare(`SELECT * FROM ${table}`).all();

    if (rows.length === 0) {
      console.log(`No data in ${table}, skipping...`);
      continue;
    }

    const columns = Object.keys(rows[0]).join(', ');
    const placeholders = Object.keys(rows[0]).map(() => '?').join(', ');

    const insertSql = `INSERT INTO ${table} (${columns}) VALUES (${placeholders}) ON CONFLICT DO NOTHING`;

    for (const row of rows) {
      const values = Object.values(row);
      await runPostgresQuery(insertSql, values, 'run');
    }

    console.log(`Migrated ${rows.length} rows from ${table}`);
  }

  sqliteDb.close();
  console.log('Migration completed successfully');
}

// Graceful shutdown
export async function closePostgresPool() {
  await pool.end();
}

import { randomUUID } from 'crypto';
import os from 'os';
import path from 'path';
import { LogRotator, TimeBasedRotator } from './rotation.js';

export type LogLevel = 'info' | 'warn' | 'error' | 'debug';

export interface LogContext {
  requestId?: string;
  route?: string;
  method?: string;
  service?: string;
  [key: string]: unknown;
}

const parseLevel = (value: string | undefined): LogLevel => {
  // Default to 'info' in production, 'debug' in development
  const defaultLevel = process.env.NODE_ENV === 'production' ? 'info' : 'debug';
  const normalized = (value || defaultLevel).toLowerCase();
  if (normalized === 'debug' || normalized === 'info' || normalized === 'warn' || normalized === 'error') {
    return normalized;
  }
  return 'info';
};

const minimumLevel = parseLevel(process.env.LOG_LEVEL);
const levelOrder: Record<LogLevel, number> = {
  debug: 10,
  info: 20,
  warn: 30,
  error: 40
};

const shouldLog = (level: LogLevel): boolean => levelOrder[level] >= levelOrder[minimumLevel];

// Log rotation setup
const logDir = process.env.LOG_DIR || path.join(process.cwd(), 'logs');
const logFile = path.join(logDir, 'trading-system.log');

// Ensure log directory exists
try {
  if (!require('fs').existsSync(logDir)) {
    require('fs').mkdirSync(logDir, { recursive: true });
  }
} catch (e) {
  // If we can't create log directory, fall back to stdout/stderr only
}

const sizeRotator = new LogRotator(logFile, {
  maxSizeBytes: 10 * 1024 * 1024, // 10MB
  maxFiles: 5,
  compress: false
});

const timeRotator = new TimeBasedRotator(logFile, {
  maxFiles: 7, // Keep 7 days of logs
  compress: false
});

// Start periodic checks
sizeRotator.startPeriodicCheck(60000); // Check every minute
timeRotator.checkAndRotate(); // Check on startup

function writeLogLine(line: string) {
  // Write to stdout/stderr
  if (line.includes('"level":"error"')) {
    process.stderr.write(`${line}\n`);
  } else {
    process.stdout.write(`${line}\n`);
  }

  // Write to file with rotation
  try {
    if (require('fs').existsSync(logDir)) {
      // Check for time-based rotation
      timeRotator.checkAndRotate();

      // Check for size-based rotation
      if (sizeRotator.needsRotation()) {
        sizeRotator.rotate();
      }

      require('fs').appendFileSync(logFile, `${line}\n`);
    }
  } catch (e) {
    // If file write fails, continue with stdout/stderr only
  }
}

function write(level: LogLevel, message: string, context: LogContext = {}) {
  if (!shouldLog(level)) return;

  const payload = {
    ts: new Date().toISOString(),
    level,
    message,
    service: context.service || 'trading-system',
    pid: process.pid,
    hostname: os.hostname(),
    ...context
  };

  const line = JSON.stringify(payload);
  writeLogLine(line);
}

export const logger = {
  debug: (message: string, context?: LogContext) => write('debug', message, context),
  info: (message: string, context?: LogContext) => write('info', message, context),
  warn: (message: string, context?: LogContext) => write('warn', message, context),
  error: (message: string, context?: LogContext) => write('error', message, context)
};

export function getRequestId(headerValue?: string | string[]): string {
  if (Array.isArray(headerValue)) {
    return headerValue[0] || randomUUID();
  }

  return typeof headerValue === 'string' && headerValue.trim().length > 0
    ? headerValue.trim()
    : randomUUID();
}

import fs from 'fs';
import path from 'path';
import { fileURLToPath } from 'url';

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);

export interface RotationConfig {
  maxSizeBytes: number;      // e.g., 10 * 1024 * 1024 for 10MB
  maxFiles: number;          // e.g., 5 to keep last 5 files
  compress: boolean;         // whether to gzip old logs
}

const DEFAULT_CONFIG: RotationConfig = {
  maxSizeBytes: 10 * 1024 * 1024, // 10MB
  maxFiles: 5,
  compress: false
};

export class LogRotator {
  private logFilePath: string;
  private config: RotationConfig;
  private checkInterval: NodeJS.Timeout | null = null;

  constructor(logFilePath: string, config: Partial<RotationConfig> = {}) {
    this.logFilePath = logFilePath;
    this.config = { ...DEFAULT_CONFIG, ...config };
  }

  /**
   * Check if log file needs rotation based on size
   */
  needsRotation(): boolean {
    try {
      if (!fs.existsSync(this.logFilePath)) {
        return false;
      }
      const stats = fs.statSync(this.logFilePath);
      return stats.size >= this.config.maxSizeBytes;
    } catch (error) {
      console.error('Error checking log file size:', error);
      return false;
    }
  }

  /**
   * Rotate the log file
   */
  rotate(): boolean {
    try {
      if (!fs.existsSync(this.logFilePath)) {
        return false;
      }

      const timestamp = new Date().toISOString().replace(/[:.]/g, '-');
      const rotatedPath = `${this.logFilePath}.${timestamp}`;

      // Rename current log file
      fs.renameSync(this.logFilePath, rotatedPath);

      // Compress if enabled
      if (this.config.compress) {
        this.compressFile(rotatedPath);
      }

      // Clean up old files
      this.cleanupOldFiles();

      return true;
    } catch (error) {
      console.error('Error rotating log file:', error);
      return false;
    }
  }

  /**
   * Compress a log file using gzip
   */
  private compressFile(filePath: string): void {
    import('zlib').then(({ gzipSync }) => {
      try {
        const data = fs.readFileSync(filePath);
        const compressed = gzipSync(data);
        fs.writeFileSync(`${filePath}.gz`, compressed);
        fs.unlinkSync(filePath);
      } catch (error) {
        console.error('Error compressing log file:', error);
      }
    }).catch(() => {});
  }

  /**
   * Remove old rotated files beyond maxFiles limit
   */
  private cleanupOldFiles(): void {
    try {
      const logDir = path.dirname(this.logFilePath);
      const logBasename = path.basename(this.logFilePath);
      const files = fs.readdirSync(logDir)
        .filter(f => f.startsWith(logBasename) && f !== logBasename)
        .map(f => ({
          name: f,
          path: path.join(logDir, f),
          time: fs.statSync(path.join(logDir, f)).mtimeMs
        }))
        .sort((a, b) => b.time - a.time);

      // Remove files beyond maxFiles limit
      for (let i = this.config.maxFiles - 1; i < files.length; i++) {
        try {
          fs.unlinkSync(files[i].path);
        } catch (error) {
          console.error(`Error removing old log file ${files[i].path}:`, error);
        }
      }
    } catch (error) {
      console.error('Error cleaning up old log files:', error);
    }
  }

  /**
   * Start periodic rotation check
   */
  startPeriodicCheck(intervalMs: number = 60000): void {
    if (this.checkInterval) {
      return;
    }
    this.checkInterval = setInterval(() => {
      if (this.needsRotation()) {
        this.rotate();
      }
    }, intervalMs);
    this.checkInterval.unref?.();
  }

  /**
   * Stop periodic rotation check
   */
  stopPeriodicCheck(): void {
    if (this.checkInterval) {
      clearInterval(this.checkInterval);
      this.checkInterval = null;
    }
  }
}

/**
 * Daily time-based rotation utility
 */
export class TimeBasedRotator {
  private logFilePath: string;
  private lastRotationDate: string;
  private config: RotationConfig;

  constructor(logFilePath: string, config: Partial<RotationConfig> = {}) {
    this.logFilePath = logFilePath;
    this.config = { ...DEFAULT_CONFIG, ...config };
    this.lastRotationDate = new Date().toISOString().split('T')[0];
  }

  /**
   * Check if a new day has started and rotate if needed
   */
  checkAndRotate(): boolean {
    const today = new Date().toISOString().split('T')[0];
    if (today !== this.lastRotationDate) {
      this.lastRotationDate = today;
      return this.rotate();
    }
    return false;
  }

  /**
   * Rotate the log file (time-based)
   */
  rotate(): boolean {
    try {
      if (!fs.existsSync(this.logFilePath)) {
        return false;
      }

      const yesterday = new Date(Date.now() - 86400000).toISOString().split('T')[0];
      const rotatedPath = `${this.logFilePath}.${yesterday}`;

      // Remove existing rotated file for this date
      if (fs.existsSync(rotatedPath)) {
        fs.unlinkSync(rotatedPath);
      }

      // Rename current log file
      fs.renameSync(this.logFilePath, rotatedPath);

      // Compress if enabled
      if (this.config.compress) {
        this.compressFile(rotatedPath);
      }

      // Clean up old files
      this.cleanupOldFiles();

      return true;
    } catch (error) {
      console.error('Error rotating log file:', error);
      return false;
    }
  }

  private compressFile(filePath: string): void {
    import('zlib').then(({ gzipSync }) => {
      try {
        const data = fs.readFileSync(filePath);
        const compressed = gzipSync(data);
        fs.writeFileSync(`${filePath}.gz`, compressed);
        fs.unlinkSync(filePath);
      } catch (error) {
        console.error('Error compressing log file:', error);
      }
    }).catch(() => {});
  }

  private cleanupOldFiles(): void {
    try {
      const logDir = path.dirname(this.logFilePath);
      const logBasename = path.basename(this.logFilePath);
      const files = fs.readdirSync(logDir)
        .filter(f => f.startsWith(logBasename) && f !== logBasename)
        .map(f => ({
          name: f,
          path: path.join(logDir, f),
          time: fs.statSync(path.join(logDir, f)).mtimeMs
        }))
        .sort((a, b) => b.time - a.time);

      for (let i = this.config.maxFiles - 1; i < files.length; i++) {
        try {
          fs.unlinkSync(files[i].path);
        } catch (error) {
          console.error(`Error removing old log file ${files[i].path}:`, error);
        }
      }
    } catch (error) {
      console.error('Error cleaning up old log files:', error);
    }
  }
}
